  let filePath = req.url === '/' ? '/streaming-demo.html' : req.url;
  const ext = path.extname(filePath);
  const mimeTypes = {
    '.html': 'text/html',
    '.js': 'text/javascript',
    '.css': 'text/css',
    '.json': 'application/json'
  };

  const fullPath = path.join(__dirname, 'demo', filePath);
